compliant:
import { Effect } from "effect"

export interface DeviceEnrollment {
  readonly deviceId: string
  readonly tenantId: string
  readonly enrolledAt: string
  readonly metadata?: Readonly<Record<string, string>>
  readonly extensions?: Readonly<Record<string, unknown>>
}

export interface EnrollmentBackend {
  readonly put: (key: string, value: string) => Effect.Effect<void>
  readonly remove: (key: string) => Effect.Effect<void>
}

const enrollmentKey = (deviceId: string): string =>
  `device-enrollments/${encodeURIComponent(deviceId)}`

export const makeEnrollmentStore = (backend: EnrollmentBackend) => {
  const replace = (record: DeviceEnrollment): Effect.Effect<void> =>
    backend.put(
      enrollmentKey(record.deviceId),
      JSON.stringify(record)
    )

  const remove = (deviceId: string): Effect.Effect<void> =>
    backend.remove(enrollmentKey(deviceId))

  return { replace, remove }
}
